<script setup lang="ts">defineProps<{hasDraft:boolean;valid:boolean;generating:boolean;previewing:boolean;publishing:boolean;canPublish:boolean;published:boolean}>();defineEmits<{validate:[];preview:[];publish:[]}>();</script>
<template><div class="ai-toolbar"><span v-if="hasDraft&&!published" class="unpublished">● Unpublished changes</span><span v-if="published" class="published">✓ Published</span><span class="spacer"/><button :disabled="!hasDraft||generating" @click="$emit('validate')">Validate</button><button :disabled="!valid||previewing" @click="$emit('preview')">{{previewing?'Loading preview…':'Preview'}}</button><button class="primary" :disabled="!valid||!canPublish||publishing||published" @click="$emit('publish')">{{publishing?'Publishing…':'Publish'}}</button></div></template>
